    double solve_rec(const uint8_t ops[8], int len, const double w[6], int r, int* best_act, double q_out[5]) {
        double vs = v_stop(w);
        double ev_app = 0.0;
        for (int s = 0; s < 6; ++s) ev_app += w[s] * PAYOFFS[s];
        if (q_out) {
            q_out[0] = 0.0;
            q_out[1] = ev_app;
            q_out[2] = q_out[3] = q_out[4] = -1e9;
