        for (int i = 0; i < len; ++i) {
            key = (key << 5) | (ops[i] + 1);
        }
        if (!best_act && !q_out) {
            auto it = memo.find(key);
            if (it != memo.end()) return it->second;
        }

        double best_v = vs;
        uint8_t next_ops[8];
        for (int k = 0; k < 3; ++k) {
            double ev_k = -COST * sum_w;
