            if (ev_k > best_v) {
                best_v = ev_k;
                if (best_act) *best_act = 2 + k;
            }
        }
        if (q_out) {
            q_out[0] = 0.0;
            q_out[1] = ev_app / sum_w;
        }
        if (!best_act && !q_out) {
            memo[key] = best_v;
        }
        return best_v;
    }
};

