#include <cmath>
#include <algorithm>
#include <cstdint>
#include <vector>

static const double PAYOFFS[6] = {660.0, 150.0, -1040.0, -4100.0, -9200.0, -14300.0};
static const double COST = 20.0;

struct HashEntry {
    uint64_t key = 0;
    double val = 0.0;
    int8_t act = -1;
};

struct FastMap {
    std::vector<HashEntry> table;
    uint64_t mask;
    FastMap(size_t cap_pow2 = 65536) : table(cap_pow2), mask(cap_pow2 - 1) {}

    inline HashEntry* find(uint64_t key) {
        uint64_t h = (key * 11400714819323198485ULL) & mask;
        while (table[h].key != 0) {
            if (table[h].key == key) return &table[h];
            h = (h + 1) & mask;
        }
        return nullptr;
    }

    inline void insert(uint64_t key, double val, int8_t act) {
        uint64_t h = (key * 11400714819323198485ULL) & mask;
        while (table[h].key != 0 && table[h].key != key) {
            h = (h + 1) & mask;
        }
        table[h].key = key;
        table[h].val = val;
        table[h].act = act;
    }
};

struct Solver {
    double P[3][6][6];
    FastMap memo;

    Solver() : memo(262144) {}

    inline double v_stop(const double w[6], int* best_act) const {
        double ev = 0.0;
        for (int s = 0; s < 6; ++s) ev += w[s] * PAYOFFS[s];
        if (best_act) *best_act = (ev > 0.0) ? 1 : 0;
        return ev > 0.0 ? ev : 0.0;
    }

