        int act = 0;
        double vs = v_stop(w, &act);
        double sum_w = w[0] + w[1] + w[2] + w[3] + w[4] + w[5];
        double ev_pi = w[0] * 660.0 + w[1] * 150.0;
        if (-COST * sum_w + ev_pi <= vs + 1e-12) {
            if (best_act) *best_act = act;
            return vs;
        }
        double best_v = vs;
        for (int k = 0; k < 3; ++k) {
            double ev_k = -COST * sum_w;
            for (int b = 0; b < 6; ++b) {
                double ev_b = 0.0;
                for (int s = 0; s < 6; ++s) {
                    ev_b += w[s] * P[k][s][b] * PAYOFFS[s];
                }
                if (ev_b > 0.0) ev_k += ev_b;
            }
            if (ev_k > best_v) {
                best_v = ev_k;
                act = 2 + k;
            }
        }
        if (best_act) *best_act = act;
        return best_v;
    }

    double solve_rec(const uint8_t* ops, int len, const double w[6], int r, int* best_act, double* q_out) {
        int act = 0;
        double vs = v_stop(w, &act);
        if (q_out) {
            double ev_app = 0.0;
            for (int s = 0; s < 6; ++s) ev_app += w[s] * PAYOFFS[s];
            q_out[0] = 0.0;
            q_out[1] = ev_app;
            q_out[2] = q_out[3] = q_out[4] = -1e9;
        }
        if (r == 0) {
            if (best_act) *best_act = act;
            return vs;
        }
        if (r == 1 && !q_out) return v_r1(w, best_act);

        double sum_w = w[0] + w[1] + w[2] + w[3] + w[4] + w[5];
        if (sum_w <= 1e-15) {
            if (best_act) *best_act = 0;
            return 0.0;
