            key = (key << 5) | (ops[i] + 1);
        }
        if (!q_out) {
            HashEntry* e = memo.find(key);
            if (e) {
                if (best_act) *best_act = e->act;
                return e->val;
            }
        }

        double best_v = vs;
        uint8_t next_ops[16];
        for (int k = 0; k < 3; ++k) {
            double ev_k = -COST * sum_w;
